mapper.select:
WITH RECURSIVE org_tree AS (
    SELECT id FROM ums_organization WHERE id = #{orgId}
    UNION ALL
    SELECT o.id FROM ums_organization o
    INNER JOIN org_tree ot ON o.parent_id = ot.id
)
SELECT id FROM org_tree;

WITH RECURSIVE org_path AS (
    SELECT id, parent_id FROM ums_organization WHERE id = #{orgId}
    UNION ALL
    SELECT o.id, o.parent_id FROM ums_organization o
    INNER JOIN org_path op ON o.id = op.parent_id
)
SELECT id FROM org_path ORDER BY id;
